INSERT INTO post (id, user_id, board_id, title, content, summary, cover, type, status, is_top, is_essence, view_count, reply_count, like_count, created_at) VALUES (1001, 2, 1, '《艾尔登法环》DLC 最终 BOSS 无伤打法思路分享', '苦战一周终于过了。核心思路是拉开距离等他突进后摇，二阶段注意地上的光圈，翻滚时机比进攻更重要。附上我的配装：出血太刀+灵药。新手别贪刀，三刀一滚节奏最稳。', '苦战一周终于过了。核心思路是拉开距离等他突进后摇，二阶段注意地上的光圈，翻滚时机比进攻更重要。附上我的配装：出血太刀+灵', NULL, 0, 0, 0, 1, 1063, 0, 140, DATE_SUB(NOW(), INTERVAL 18581 MINUTE));
INSERT INTO post (id, user_id, board_id, title, content, summary, cover, type, status, is_top, is_essence, view_count, reply_count, like_count, created_at) VALUES (1002, 11, 1, '3080 显卡玩 4K 大作到底香不香？实测帧数汇总', '最近把显示器换成了 4K 160Hz，用 3080 跑了几款大作。结论是：3A 大作想稳 60 帧得适当降点画质，竞技类完全没压力。预算够建议直接 4080 起。', '最近把显示器换成了 4K 160Hz，用 3080 跑了几款大作。结论是：3A 大作想稳 60 帧得适当降点画质，竞技类', NULL, 0, 0, 0, 0, 3076, 0, 71, DATE_SUB(NOW(), INTERVAL 16737 MINUTE));
INSERT INTO post (id, user_id, board_id, title, content, summary, cover, type, status, is_top, is_essence, view_count, reply_count, like_count, created_at) VALUES (1003, 2, 1, 'PC 端这几个神级 Mod 让老游戏焕发第二春', '推荐三个我常驻的 Mod：画质增强包、宽屏补丁、还有社区汉化。装完《上古卷轴》跟新游戏一样。记得用 Mod 管理器，别手动覆盖容易崩。', '推荐三个我常驻的 Mod：画质增强包、宽屏补丁、还有社区汉化。装完《上古卷轴》跟新游戏一样。记得用 Mod 管理器，别手', NULL, 0, 0, 0, 0, 416, 0, 279, DATE_SUB(NOW(), INTERVAL 23887 MINUTE));
INSERT INTO post (id, user_id, board_id, title, content, summary, cover, type, status, is_top, is_essence, view_count, reply_count, like_count, created_at) VALUES (1004, 14, 1, '今年配一台 2K 高刷主机怎么选配件不踩坑', '主板别买太丐的，供电够用就行；内存 32G 起步；电源留足余量。最重要的还是显卡，预算分配上显卡至少占一半。', '主板别买太丐的，供电够用就行；内存 32G 起步；电源留足余量。最重要的还是显卡，预算分配上显卡至少占一半。', NULL, 0, 0, 0, 0, 182, 0, 16, DATE_SUB(NOW(), INTERVAL 10504 MINUTE));
