-- 回帖（含楼中楼）

-- 重算板块帖子数 / 帖子回复数 / 回复楼层
UPDATE board b SET post_count = (SELECT COUNT(*) FROM post p WHERE p.board_id = b.id);
-- 父板块显示其子板块帖子数之和
UPDATE board b SET post_count = (SELECT COALESCE(SUM(c.post_count),0) FROM (SELECT parent_id, post_count FROM board) c WHERE c.parent_id = b.id) WHERE b.parent_id IS NULL;
UPDATE post p SET reply_count = (SELECT COUNT(*) FROM reply r WHERE r.post_id = p.id);
SET @last_post := 0; SET @floor := 0;
UPDATE reply r JOIN (SELECT id, post_id FROM reply ORDER BY post_id, id) o ON r.id = o.id SET r.floor = IF(@last_post = o.post_id, @floor := @floor + 1, @floor := 1 + 0*(@last_post := o.post_id));
